function woodTexture(){
  const w=256,h=512,data=new Uint8Array(w*h*4);
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){
    const u=x/w,v=y/h,warp=.009*Math.sin(v*9+u*8)+.003*Math.sin(v*27+u*12);
    const broad=Math.sin((u+warp)*57)+.45*Math.sin((u+warp*.45)*141+1.8);
    const fine=Math.sin((u+warp*.12)*871+Math.sin(v*19)*.8);
    const pores=Math.pow(Math.max(0,Math.sin((u+warp*.06)*1599+Math.sin(v*41)*.3)),8);
    const value=Math.max(100,Math.min(255,234+broad*9+fine*3-pores*9));
    const i=(y*w+x)*4;data[i]=value;data[i+1]=value;data[i+2]=value;data[i+3]=255;
  }
  const map=new THREE.DataTexture(data,w,h,THREE.RGBAFormat);map.name='Procedural light oak grain';
  if(THREE.SRGBColorSpace)map.colorSpace=THREE.SRGBColorSpace;else map.encoding=THREE.sRGBEncoding;map.magFilter=THREE.LinearFilter;map.minFilter=THREE.LinearMipmapLinearFilter;
  map.generateMipmaps=true;map.needsUpdate=true;return map;
}
