    T.detailGeos.forEach(g=>geometries.add(g));T.mats.forEach(m=>materials.add(m));geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());T.textures.forEach(t=>t.dispose());T.env?.dispose();
