  async prepareQuoteRenders(){
    if(this._quoteRenderJob)return this._quoteRenderJob;
    const spaces=this.snapshot(),key=JSON.stringify(spaces);
    if(this._quoteRenderKey===key)return true;
    this.setState({quoteRendering:true,quoteRenderError:''});
    this._quoteRenderJob=(async()=>{
      let renderer;
      try{
        if(!spaces.some(sp=>sp.items.length)){this._quoteRenders={};this._quoteRenderKey=key;this.setState({quoteRendering:false});return true;}
        if(!window.THREE)await this.three3dLoad();
        if(THREE.ColorManagement){if('legacyMode' in THREE.ColorManagement)THREE.ColorManagement.legacyMode=false;else THREE.ColorManagement.enabled=true;}
        renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,preserveDrawingBuffer:true});renderer.setPixelRatio(1);renderer.setSize(1400,900,false);
        renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
        if('outputEncoding' in renderer)renderer.outputEncoding=THREE.sRGBEncoding;
        renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1;
        const images={};
        for(const sp of spaces.filter(s=>s.items.length)){
          const T=this.quoteScene(sp,spaces,renderer);
          try{
            let timeout;try{await Promise.race([Promise.all(T.textureLoads),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(new Error('Material images took too long to load.')),15000);})]);}finally{clearTimeout(timeout);}
            if(T.textureFailed)throw new Error('A material image could not load.');
            const left=sp.items.some(it=>this.geo(it)?.handedCorner&&it.cornerTurn==='left');
            images[sp.id]=[['Perspective',left?[1,.7,1.25]:[-.8,.7,1.25]],['Front',[0,.05,1]]].map(([label,dir])=>{
              renderer.render(T.scene,this.quoteCamera(T,dir));return {label,url:renderer.domElement.toDataURL('image/jpeg',.93)};
            });
          }finally{this.disposeQuoteScene(T);}
        }
        if(JSON.stringify(this.state.spaces)!==key)throw new Error('The design changed. Please refresh the renderings.');
        this._quoteRenders=images;this._quoteRenderKey=key;this.setState({quoteRendering:false});return true;
      }catch(error){this.setState({quoteRendering:false,quoteRenderError:'Renderings are not ready. '+(error.message||'Please try again.')});return false;}
      finally{if(renderer){renderer.dispose();renderer.forceContextLoss?.();}}
    })();
    try{return await this._quoteRenderJob;}finally{this._quoteRenderJob=null;}
  }
