    const p=this.prod(it.sku)||it,g=it.sku?this.geo(it):p;
    const normal=v=>({cooktop:'hob',hood:'extractor','cooker hood':'extractor','range hood':'extractor'}[String(v).toLowerCase()]||String(v).toLowerCase());
    const roles=[...(p.applianceRoles||[]),...(p.appliances||[]).map(a=>a.role||a.kind||a),...(it.appliances||[]).map(a=>a.role||a.kind||a)].map(normal);
    const recipe=CabinetElevation.recipes[g?.model||g?.id];
    if(recipe?.surface==='hob')roles.push('hob');if(recipe?.appliance==='hood')roles.push('extractor');
    return [...new Set(roles)];
