    const rule=this.pairingRule(source),g=this.geo(source),p=product;
    let tg=target?this.geo(target):p;
    if(!rule||!g||!this.productRoles(p).includes(rule.target))return {reason:'No compatible product relationship.'};
    const meta=p.pairing||{},sourceMeta=this.prod(source.sku)?.pairing||{};
    const required=sourceMeta.applianceWidth||g.w;
    if(meta.matchHobWidth)tg={...tg,w:required};
