    if(g.free&&!meta.supportsIsland)return {reason:'This catalogue extractor is wall-mounted; an island extractor is required.'};
    if(tg.mount<=0||g.mount>=400||g.h>1200)return {reason:'The hob and extractor must stay in their base and upper zones.'};
