      const pose=this.v3dPlace(sp,it,g),group=new THREE.Group();group.userData.ledCabinet=it.uid;
      group.position.set(this.m3(pose.cx),0,this.m3(pose.cz));group.rotation.y=pose.angle||0;
      const strip=this.v3dSpan(-g.w/2+30,g.w/2-30,g.mount-9,g.mount-4,g.d/2-75,g.d/2-61,on?'led-on':'led-off');
      strip.name='3000K under-cabinet LED';strip.castShadow=false;group.add(strip);
