    if(selected)return this.mutate(sp=>{const it=sp.items.find(i=>i.uid===selected.uid);it[(carcass||this.prod(it.sku)?.wallPanel)?'carcassFinishId':'doorPanelFinishId']=id;});
    if(this.space().room==='wardrobe'||scope==='selected'){this.flash('Select an object to edit its finish.');return false;}
