    if(g.bedroomFactory==='createBedModule')Object.assign(p,{bedWidth:g.w/1000,bedLength:g.d/1000});
    if(g.bedroomFactory==='createTableModule')Object.assign(p,{tableWidth:g.w/1000,tableHeight:g.h/1000,tableDepth:g.d/1000});
    if(g.bedroomFactory==='createBedroomWardrobeModule')Object.assign(p,{wardrobeWidth:g.w/1000,height:g.h/1000,wardrobeDepth:g.d/1000});
    if(g.bedroomFactory==='createSideCabinetModule')Object.assign(p,{sideWidth:g.w/1000,height:g.h/1000,sideDepth:g.d/1000});
