  if(source.walls?.length)issues.push('Custom wall records need a verified room-footprint adapter before automatic design.');
  if(source.roomShape&&!['rect','rectangular'].includes(source.roomShape)||source.slopedCeiling||source.ceilingZones?.length||source.footprint?.length>4)issues.push('This room shape or ceiling is not supported by the rectangular prototype. Continue manually.');
  if(!s.confirmed||![R.w,R.d,R.h].every(n=>n>0&&n<=D.maxRoom))issues.push('Complete Room Setup: confirm the full rectangular footprint, width, depth and height.');
  for(const key of ['openingsReviewed','obstaclesReviewed','servicesReviewed','assumptionsAccepted'])if(!s[key])issues.push('Complete Room Setup: '+({openingsReviewed:'review all doors, door swings and windows',obstaclesReviewed:'review columns, beams and restricted areas',servicesReviewed:'review services and their mobility',assumptionsAccepted:'review and accept the prototype clearance assumptions'}[key])+'.');
  for(const key of ['entrance','grocery',...(s.diningDisconnected?[]:['dining'])])if(!s[key]||![s[key].x,s[key].z].every(finite)||s[key].x<0||s[key].x>R.w||s[key].z<0||s[key].z>R.d)issues.push('Mark '+key+' on the room plan.');
  if(!finite(s.entranceWidth)||Number(s.entranceWidth)<D.walkway)issues.push('Confirm an entrance width of at least '+D.walkway+' mm for this prototype.');
  const openings=s.openings||[],obstacles=s.obstacles||[],services=s.services||[];
