  if(!a.appliances.includes('fridge'))issues.push('This initial workflow pack requires a supported fridge station. An external-fridge workflow needs designer review.');
  if(!a.appliances.includes('hob'))issues.push('This initial cooking workflow pack requires a hob and compatible hood. Oven-only kitchens need a separate workflow pack.');
  if(a.cleaning!=='hand'&&!a.appliances.includes('dishwasher'))issues.push('Your cleaning routine uses a dishwasher. Add it or change the cleaning answer.');
  if(a.activities.includes('baking')&&!a.appliances.includes('oven'))issues.push('Baking needs the supported oven housing. Add an oven or adjust activities.');
  if(issues.length)fail([...new Set(issues)].join('\n'));
  const boxFor=o=>{const dep=o.kind==='door'?(o.swing.startsWith('in')?Math.max(Number(o.width),D.walkway):D.walkway):D.cabinetDepth;
   return o.wall==='back'?{x:+o.start,z:0,w:+o.width,d:dep}:o.wall==='front'?{x:+o.start,z:R.d-dep,w:+o.width,d:dep}:o.wall==='left'?{x:0,z:+o.start,w:dep,d:+o.width}:{x:R.w-dep,z:+o.start,w:dep,d:+o.width};};
  const blocks=[...obstacles.map(b=>({x:+b.x,z:+b.z,w:+b.w,d:+b.d,kind:b.kind||'restricted'})),...openings.map(o=>({...boxFor(o),kind:o.kind}))];
  const assumptions=[r.certification,'Door/drawer/appliance operating envelopes use conservative prototype dimensions; confirm actual appliance brands, handing and clearances.','Storage capacity is an external-volume proxy, not net litres.','The cold/freezer route assumes a combined fridge-freezer in the selected housing; appliance model needs confirmation.','Waste is allocated to accessible under-sink storage; unconfirmed bin hardware is not included.','Windows and beams reserve their full floor columns conservatively.','Service valves are assumed accessible from the appliance standing position; concealed installation needs technician review.','Boundary entrance/dining markers are projected just inside the room for a person-sized navigation start.', 'Exposed end panels are included by the existing model. No unverified filler or corner mechanism is invented.',...services.filter(p=>p.mobility==='unknown').map(p=>'Unknown '+p.kind+' for '+p.role+': new connection position proposed; technician must confirm before installation.'),...(s.diningDisconnected?['Dining is not directly connected: serving and dirty returns use the kitchen entrance.']:[])];
  const doorLeaves=openings.filter(o=>o.kind==='door'&&o.swing.startsWith('in')).map(o=>{const hinge=Number(o.start)+(o.swing.endsWith('right')?Number(o.width):0),t=D.doorLeafThickness;return o.wall==='back'?{x:hinge-t/2,z:0,w:t,d:+o.width}:o.wall==='front'?{x:hinge-t/2,z:R.d-o.width,w:t,d:+o.width}:o.wall==='left'?{x:0,z:hinge-t/2,w:+o.width,d:t}:{x:R.w-o.width,z:hinge-t/2,w:+o.width,d:t};});
