  return {R,setup:copy(s),blocks,navBlocks,services:copy(services),assumptions,derived:derived(a,r),walls:['back','left','right'].filter(w=>s.usableWalls?.[w]!==false).map(w=>({wall:w,length:w==='back'?R.w:R.d,angle:angle[w]}))};
