  return rows.map(r=>({...r,amount:this.ifMoney(pr.rows.find(p=>p.key===r.key&&p.label===r.label)?.amount??0).replace('USD ',''),modules:r.modules.map(m=>({...m,unitLabel:m.unit==null?'Estimated Price on request':'Estimated Price · '+this.ifMoney(m.unit)+' each',subtotal:this.ifMoney(m.amount).replace('USD ',''),roundingNote:''}))}));
