const roomsLabel=p=>{const r=roomsOf(p);return r.length>1?(roomDef(r[0]).name+' +'+(r.length-1)):roomDef(r[0]).name;};
const nameNote=d=>nameTaken(d)
 ? {bad:true, text:'A project called “'+((d&&d.name||'').trim())+'” already exists. Give this one a different name so the two stay apart in your workspace.'}
 : {bad:false,text:'Each project covers one room, so a name that says which room helps — for example “Living Room — Maple Street”.'};
const nameTaken=d=>{
 const n=(d&&d.name||'').trim().toLowerCase();
 if(!n)return false;
 return RM.projects.some(x=>x.id!==d.id&&(x.name||'').trim().toLowerCase()===n);
};
const blankProject=()=>({id:uid(),name:'',client:'',scenario:'living',rooms:['living'],method:'manual',createdAt:Date.now(),updatedAt:Date.now(),
   done:[],appliances:[],style:'',openings:[],openingSource:'manual',utilities:[],utilitiesSeeded:false});

